import sys
import os
import time


class CodeforcesC:

    def __init__(self):
        self.ONLINE_JUDGE = os.environ.get('ONLINE_JUDGE') is not None
        self.tok = iter([])
        self.DEBUG = False
        self.timeBegin = 0
        self.timeEnd = 0

    def init(self):
        if self.ONLINE_JUDGE:
            self.in_ = sys.stdin
            self.out = sys.stdout
        else:
            self.in_ = open("input.txt", "r")
            self.out = open("output.txt", "w")

    def readString(self):
        while True:
            try:
                return next(self.tok)
            except StopIteration:
                line = self.in_.readline()
                if not line:
                    return None
                self.tok = iter(line.split())

    def readInt(self):
        return int(self.readString())

    def readLong(self):
        return int(self.readString())

    def readDouble(self):
        return float(self.readString())

    def time(self):
        self.timeEnd = int(round(time.time() * 1000))
        sys.stderr.write("Time = " + str(self.timeEnd - self.timeBegin) + "\n")

    def memory(self):
        pass

    def debug(self, *objects):
        if self.DEBUG:
            for o in objects:
                sys.stderr.write(str(o) + "\n")

    def readIntArray(self, n):
        return [self.readInt() for _ in range(n)]

    def run(self):
        try:
            self.timeBegin = int(round(time.time() * 1000))
            self.init()
            self.solve()
            if self.out is not sys.stdout:
                self.out.close()
            self.time()
            self.memory()
        except Exception:
            import traceback
            traceback.print_exc(file=sys.stderr)
            sys.exit(-1)

    def solve(self):

        l = self.readInt()
        r = self.readInt()

        n = 9
        ten = [0] * (n + 1)

        ten[0] = 1

        for i in range(1, n + 1):
            ten[i] = 10 * ten[i - 1]

        answer = 0

        luckyNumbers = []

        for length in range(1, n + 1):
            for cur in range(1 << length):
                value = 0
                for j in range(length):
                    if ((1 << j) & cur) == (1 << j):
                        value += ten[j] * 7
                    else:
                        value += ten[j] * 4
                # self.out.write(str(value) + "\n")
                luckyNumbers.append(value)

        luckyNumbers.append(4444444444)

        lastNumber = l

        for luckyNumber in luckyNumbers:
            if luckyNumber > r:
                answer += (r - lastNumber + 1) * luckyNumber
                break
            if luckyNumber >= l:
                answer += (luckyNumber - lastNumber + 1) * luckyNumber
                lastNumber = luckyNumber + 1

        self.out.write(str(answer) + "\n")


def main():
    sys.setrecursionlimit(1 << 20)
    CodeforcesC().run()


if __name__ == "__main__":
    import threading
    threading.stack_size(128 * (1 << 20))
    t = threading.Thread(target=main)
    t.start()
    t.join()
